import{_ as r,c as a,o as t,ag as i}from"./chunks/framework.Vyheyqg9.js";const m=JSON.parse('{"title":"Performance source mapping and merge decisions","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/performance/sources.md","filePath":"frontend/performance/sources.md"}'),o={name:"frontend/performance/sources.md"};function n(s,e,d,c,l,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="performance-source-mapping-and-merge-decisions" tabindex="-1">Performance source mapping and merge decisions <a class="header-anchor" href="#performance-source-mapping-and-merge-decisions" aria-label="Permalink to “Performance source mapping and merge decisions”">​</a></h1><p>Merged <strong>2026-10-28</strong>. This learning path combines existing frontend/senior-growth explanations with the user-supplied EPAM <strong>Web Performance</strong> self-study extracts, tools homework, six additional task descriptions and accompanying figures. The EPAM category pages were inaccessible through browsing during the initial review; the supplied text is the evidence for their contents. The private template repository was not cloned or executed.</p><h2 id="where-each-module-now-belongs" tabindex="-1"><span class="hub-section-number">1 </span>Where each module now belongs <a class="header-anchor" href="#where-each-module-now-belongs" aria-label="Permalink to “1 Where each module now belongs”">​</a></h2><table tabindex="0"><thead><tr><th>Supplied material</th><th>Merged teaching owner</th><th>Practice</th></tr></thead><tbody><tr><td>Module 1: metrics</td><td><a href="./measurement.html">Measurement</a>, with current INP and complete CLS coverage</td><td>H1 investigation and H3 regression report</td></tr><tr><td>Module 2: tools and food-card audit</td><td><a href="./measurement.html">Measurement</a>; compression and resource diagnosis in <a href="./delivery.html">delivery</a> / <a href="./caching.html">caching</a></td><td>H1 baseline, H2 isolated changes</td></tr><tr><td>Module 3: link/script attributes and browser targets</td><td><a href="./delivery.html">Delivery</a>, existing script trace lab</td><td>H2 discovery; optional browser-target comparison</td></tr><tr><td>Module 4: images</td><td><a href="./images.html">Images</a></td><td>H2 asset option; optional exact course compatibility exercise</td></tr><tr><td>Critical CSS and font optimization</td><td><a href="./css-fonts.html">CSS/fonts</a>, existing font calibration</td><td>H2 asset option; optional extraction and two-family comparison</td></tr><tr><td>Module 6: PRPL, splitting, Lodash and analyzer</td><td><a href="./delivery.html">Delivery</a>, existing production module-graph fixture</td><td>H2 delivery option; optional two-entry Webpack comparison</td></tr><tr><td>Module 7: loading, CDN, caching, service workers</td><td><a href="./caching.html">Caching</a> and <a href="./runtime.html">runtime</a></td><td>H2 interaction, H3 delivery plan; optional worker/offline labs</td></tr></tbody></table><p>The <a href="./../../senior_growth/Web_Performance/">existing senior-growth catalogue</a> continues to own its worked debounce/search, layout, animation, memory, script-order, bundle and SSR examples. The new path supplies ordering, missing asset/cache explanations and explicit modern corrections. <a href="./../../practice/frontend/performance/">Homework</a> refines E02 and P-328/P-329; it does not require another unrelated product.</p><h2 id="corrections-preserved-in-the-teaching" tabindex="-1"><span class="hub-section-number">2 </span>Corrections preserved in the teaching <a class="header-anchor" href="#corrections-preserved-in-the-teaching" aria-label="Permalink to “2 Corrections preserved in the teaching”">​</a></h2><ul><li>Current Core Web Vitals are LCP, INP and CLS. FID/FMP/TTI are historical context; load events do not establish readiness.</li><li>Async network requests do not normally occupy the page thread while awaiting bytes. Parsing, execution, style/layout and data processing have different costs.</li><li><code>defer</code> changes parser timing, not the execution cost; a display&#39;s refresh rate changes its available frame time.</li><li>Use <code>fetchpriority</code>, current script/module semantics, feature detection and an explicit support policy. Old compatibility grids and fixed global browser-share thresholds are not current support evidence.</li><li>Valid <code>picture</code>/<code>img</code> markup, <code>sizes</code>, DPR, reserved dimensions and eager LCP content replace the invalid alternative image example and indiscriminate lazy-loading advice.</li><li>Font subsets are generated assets; <code>unicode-range</code> alone does not shrink binaries. Neither <code>local()</code> nor two formats nor a particular plugin is universally required.</li><li>Styles/polyfills can be side-effectful. Correctly distinguish <code>usedExports</code> from <code>providedExports</code>, shared chunks, deep imports and ESM tree shaking.</li><li>Dedicated Web Workers are the default computation exercise; service workers teach request/offline lifecycle. Old storage APIs and incomplete cache snippets are not copied as working solutions.</li><li>HTTP validation and application Cache Storage policies differ. A CDN or service worker is not an automatic speed guarantee.</li><li>Coursework penalties, grade bands, mentor access and “change only under comments” restrictions remain original-course context. They do not direct repository actions or become rules for these local learning exercises.</li></ul><p>If submitting the original EPAM assignment, use its actual template, support requirements and rubric. A modernized local exercise does not claim equivalence to its grader. No private-repository access, hosting setup, publication or remote push is part of this merge.</p><h2 id="visual-provenance" tabindex="-1"><span class="hub-section-number">3 </span>Visual provenance <a class="header-anchor" href="#visual-provenance" aria-label="Permalink to “3 Visual provenance”">​</a></h2><p>Two figures were copied from the user&#39;s supplied course attachments into the repository so lessons do not depend on temporary clipboard paths:</p><table tabindex="0"><thead><tr><th>Local asset</th><th>Supplied figure</th><th>How it is used</th></tr></thead><tbody><tr><td><code>images/performance/first-contentful-paint.png</code></td><td>Image #7, first paint versus contentful paint</td><td>Conceptual stages; illustrative times explicitly marked</td></tr><tr><td><code>images/performance/eager-lazy.png</code></td><td>Image #29, eager versus lazy loading</td><td>Conceptual offscreen savings; eager hero exception explained</td></tr></tbody></table><p>Original authorship/license was not established from the pasted extracts; retain this provenance and verify redistribution rights before republishing these supplied figures beyond the learning repository. Mermaid diagrams are newly authored simplified teaching models: investigation loop, LCP phases, resource graph, responsive selection, CSS delivery, rendering pipeline, worker messaging, HTTP validation and service-worker lifecycle. Historical TTI/FID dashboards and provider-console images are omitted from the current teaching to avoid presenting them as up-to-date procedures.</p><h2 id="supplementary-official-reading" tabindex="-1"><span class="hub-section-number">4 </span>Supplementary official reading <a class="header-anchor" href="#supplementary-official-reading" aria-label="Permalink to “4 Supplementary official reading”">​</a></h2><p>Use references beside each lesson for exact contracts. Broader reinforcement: <a href="https://web.dev/learn/performance" target="_blank" rel="noreferrer">Learn Performance</a>, <a href="https://developer.chrome.com/docs/devtools/performance/overview" target="_blank" rel="noreferrer">Chrome Performance panel</a>, <a href="https://web.dev/articles/vitals" target="_blank" rel="noreferrer">Core Web Vitals</a>, <a href="https://webpack.js.org/guides/tree-shaking/" target="_blank" rel="noreferrer">Webpack tree shaking</a>, <a href="https://developer.mozilla.org/en-US/docs/Web/API/Web_Workers_API/Using_web_workers" target="_blank" rel="noreferrer">Web Workers</a>, <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching" target="_blank" rel="noreferrer">HTTP caching</a>.</p><h2 id="verification-boundary" tabindex="-1"><span class="hub-section-number">5 </span>Verification boundary <a class="header-anchor" href="#verification-boundary" aria-label="Permalink to “5 Verification boundary”">​</a></h2><p>Documentation author checks are recorded in <a href="./verification.html">performance verification</a>. Code blocks with example asset paths and deployment headers are teaching fragments, not an installed application or measured improvement. Real assets, learner traces, RUM collection, browser compatibility and service-worker lifecycle results remain separate practice evidence.</p>',16)])])}const u=r(o,[["render",n]]);export{m as __pageData,u as default};
